INSERT INTO `enterprises` VALUES ('10000000-0000-4000-8000-000000000003','FPT Software','active','/assets/images/fpt-software-logo.svg','Công nghệ thông tin & Dịch vụ phần mềm','10,000+ nhân viên',1999,'FPT Software là công ty công nghệ và dịch vụ CNTT hàng đầu thế giới có trụ sở chính tại Việt Nam, tiên phong trong chuyển đổi số, AI và đào tạo phát triển tài năng trẻ.','business@test.talenthub.local','024 7300 7575','https://fptsoftware.com','0101234567','Tòa nhà FPT, Phố Duy Tân, Phường Dịch Vọng Hậu, Quận Cầu Giấy, Hà Nội','verified',NULL,NULL,NULL,'2026-08-16 02:32:12.640493','2026-08-26 07:10:33.081182'),('32000000-0000-4000-8000-000000000002','VNG Corporation','active','/assets/images/vng-logo.svg','Công nghệ, Game & Giải trí số','3,000+ nhân viên',2004,'VNG là kỳ lân công nghệ đầu tiên của Việt Nam, dẫn đầu trong lĩnh vực phát triển Game số, nền tảng giao tiếp Zalo, giải pháp đám mây và thanh toán điện tử.','vng.careers@talenthub.local','028 3962 3888','https://vng.com.vn','0303815871','VNG Campus, Đường số 13, Khu chế xuất Tân Thuận, Quận 7, TP. Hồ Chí Minh','verified',NULL,NULL,NULL,'2026-08-26 14:08:48.302320','2026-08-26 07:10:33.081182'),('32000000-0000-4000-8000-000000000003','Shopee Vietnam (Sea Group)','active','/assets/images/shopee-logo.svg','Thương mại điện tử & Chuỗi cung ứng','5,000+ nhân viên',2015,'Shopee là nền tảng thương mại điện tử hàng đầu tại Đông Nam Á và Đài Loan, cung cấp trải nghiệm mua sắm trực tuyến liền mạch, an toàn và tối ưu bằng công nghệ phân tích dữ liệu lớn.','shopee.careers@talenthub.local','028 7308 1221','https://careers.shopee.vn','0313490089','Tầng 17, Tòa nhà Saigon Centre Tower 2, 67 Lê Lợi, Bến Nghé, Quận 1, TP. Hồ Chí Minh','verified',NULL,NULL,NULL,'2026-08-26 14:08:48.302320','2026-08-26 07:10:33.081182'),('32000000-0000-4000-8000-000000000004','Ngân hàng TMCP Kỹ thương Việt Nam (Techcombank)','active','/assets/images/techcombank-logo.svg','Tài chính, Ngân hàng & Công nghệ tài chính (Fintech)','12,000+ nhân viên',1993,'Techcombank là một trong những ngân hàng cổ phần lớn nhất Việt Nam, tiên phong trong hành trình chuyển đổi số toàn diện với ngân hàng số Techcombank Mobile và giải pháp tài chính vượt trội.','techcombank.careers@talenthub.local','024 3944 6368','https://techcombank.com','0100230800','Số 6 Quang Trung, Phường Trần Hưng Đạo, Quận Hoàn Kiếm, Hà Nội','verified',NULL,NULL,NULL,'2026-08-26 14:08:48.302320','2026-08-26 07:10:33.081182'),('32000000-0000-4000-8000-000000000005','Công ty An ninh mạng Viettel (Viettel Cyber Security)','active','/assets/images/viettel-cyber-logo.svg','An toàn thông tin & Viễn thông','1,000+ nhân viên',2014,'Viettel Cyber Security là đơn vị chuyên trách an ninh mạng hàng đầu Việt Nam thuộc Tập đoàn Công nghiệp - Viễn thông Quân đội Viettel, bảo vệ hạ tầng trọng yếu quốc gia và doanh nghiệp lớn.','viettel.cyber@talenthub.local','024 6666 8888','https://viettelcybersecurity.com','0100109106','Tòa nhà Viettel, Số 1 Trần Hữu Dực, Phường Mỹ Đình 2, Quận Nam Từ Liêm, Hà Nội','verified',NULL,NULL,NULL,'2026-08-26 14:08:48.302320','2026-08-26 07:10:33.081182'),('32000000-0000-4000-8000-000000000006','Tập đoàn Truyền thông & Quảng cáo Dentsu Vietnam','active','/assets/images/dentsu-logo.svg','Truyền thông, Quảng cáo & Sáng tạo nội dung','600+ nhân viên',2003,'Dentsu Vietnam trực thuộc mạng lưới Dentsu Quốc tế, cung cấp các giải pháp marketing số tích hợp, sáng tạo nội dung truyền thông, thiết kế thương hiệu và chiến lược tăng trưởng khách hàng.','dentsu.careers@talenthub.local','028 3821 9000','https://dentsu.com','0302821415','Tầng 16, Tòa nhà Vincom Center, 72 Lê Thánh Tôn, Bến Nghé, Quận 1, TP. Hồ Chí Minh','verified',NULL,NULL,NULL,'2026-08-26 14:08:48.302320','2026-08-26 07:10:33.081182');
