INSERT INTO `internship_posts` VALUES ('40000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000003','Thực tập sinh Trí tuệ Nhân tạo & LLM (AI/GenAI Intern)','it_software','active','public','Hà Nội & TP. Hồ Chí Minh','full_time','4-6 tháng','Đại học / Cao đẳng','Tham gia nghiên cứu và phát triển các mô hình AI/LLM, ứng dụng xử lý ngôn ngữ tự nhiên (NLP) và Computer Vision vào các dự án chuyển đổi số doanh nghiệp toàn cầu.','Trợ cấp hàng tháng từ 6.000.000 - 10.000.000 VNĐ; Cố vấn 1-1 từ AI Solution Architect; Cơ hội chuyển thẳng thành nhân viên chính thức.','[\"Python\", \"PyTorch\", \"Generative AI\", \"NLP\", \"Machine Learning\"]','[\"Sinh viên năm 3-4 chuyên ngành CNTT, Khoa học Máy tính hoặc Trí tuệ nhân tạo\", \"GPA từ 3.0/4.0 trở lên\", \"Có tư duy logic và khả năng đọc hiểu tài liệu tiếng Anh tốt\"]',5,'2026-12-31 23:59:59.000000','2026-08-26 14:08:48.323510','2026-08-26 07:10:33.082705'),('40000000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000003','Thực tập sinh Web Fullstack (NodeJS / ReactJS / Python)','it_software','active','public','Đà Nẵng & Cần Thơ','full_time','3-5 tháng','Đại học / Cao đẳng','Xây dựng các module giao diện người dùng và API RESTful cho hệ thống quản lý tài năng và dịch vụ số, phối hợp trong mô hình Scrum/Agile.','Phụ cấp thực tập hấp dẫn; Đào tạo chuẩn dự án quốc tế CMMI L5; Hỗ trợ dấu thực tập tốt nghiệp và OJT.','[\"JavaScript\", \"React\", \"NodeJS\", \"SQL\", \"Git\"]','[\"Nắm vững lập trình hướng đối tượng và cơ sở dữ liệu quan hệ\", \"Đã từng làm ít nhất 1 đồ án web bằng React hoặc Node/PHP\"]',8,'2026-12-31 23:59:59.000000','2026-08-26 14:08:48.323510','2026-08-26 07:10:33.082705'),('40000000-0000-4000-8000-000000000003','10000000-0000-4000-8000-000000000003','Kỹ sư Kiểm thử Phần mềm Tự động (Automation QA Trainee)','it_software','active','public','Hà Nội','hybrid','3-4 tháng','Đại học / Cao đẳng','Viết kịch bản kiểm thử tự động với Selenium, Playwright hoặc Cypress; kiểm thử hiệu năng và bảo mật hệ thống.','Trợ cấp thực tập 5.000.000 - 8.000.000 VNĐ; Tham gia các khóa đào tạo ISTQB miễn phí.','[\"Automation Testing\", \"Selenium\", \"Playwright\", \"Java\", \"Python\"]','[\"Tỉ mỉ, cẩn thận, có kiến thức cơ bản về quy trình kiểm thử phần mềm\"]',4,'2026-12-31 23:59:59.000000','2026-08-26 14:08:48.323510','2026-08-26 07:10:33.082705'),('40000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000000003','FPT Tech Day Experience: Trải nghiệm Nhập môn Công nghệ & AI','it_software','active','partner_schools','TP. Hồ Chí Minh & Hà Nội','part_time','2-4 tuần','Trung học Phổ thông','Chương trình kiến tập và hướng nghiệp sớm dành cho học sinh THPT. Tham gia lập trình robot cơ bản, tìm hiểu về bảo mật Internet và tham quan trung tâm dữ liệu FPT.','Chứng chỉ hoàn thành FPT Tech Experience; Quà tặng công nghệ và học bổng khuyến khích tài năng trẻ.','[\"Tư duy logic\", \"Khám phá công nghệ\", \"Làm việc nhóm\", \"Giao tiếp\"]','[\"Dành cho học sinh khối 10-12 các trường THPT đối tác\", \"Yêu thích khoa học kỹ thuật và công nghệ thông tin\"]',20,'2026-11-30 23:59:59.000000','2026-08-26 14:08:48.323510','2026-08-26 07:10:33.082705'),('40000000-0000-4000-8000-000000000005','32000000-0000-4000-8000-000000000002','2D/3D Game Artist Intern (Đồ họa & Thiết kế Nhân vật Game)','design_media','active','public','TP. Hồ Chí Minh','full_time','3-6 tháng','Đại học / Cao đẳng','Thiết kế concept art nhân vật, vũ khí, hiệu ứng VFX và môi trường cho các tựa game mobile và metaverse của VNG Game Studios.','Hỗ trợ thực tập 7.000.000 - 10.000.000 VNĐ; Làm việc tại VNG Campus với phòng gym, bể bơi và khu giải trí sáng tạo.','[\"Photoshop\", \"Blender\", \"3D Modeling\", \"Concept Art\", \"ZBrush\"]','[\"Có portfolio hoặc sản phẩm vẽ tay / 3D minh họa\", \"Đam mê ngành công nghiệp game và thẩm mỹ thị giác tốt\"]',4,'2026-12-31 23:59:59.000000','2026-08-26 14:08:48.323510','2026-08-26 07:10:33.082705'),('40000000-0000-4000-8000-000000000006','32000000-0000-4000-8000-000000000002','UI/UX Product Designer Trainee (Thiết kế Sản phẩm Số)','design_media','active','public','TP. Hồ Chí Minh','full_time','3-6 tháng','Đại học / Cao đẳng','Nghiên cứu hành vi người dùng, xây dựng wireframe, prototype tương tác và thiết kế giao diện ứng dụng số cho hệ sinh thái Zalo và Zing.','Trợ cấp thực tập cạnh tranh; Mentor bởi các Lead Designer kỳ cựu; Cơ hội làm việc trên sản phẩm hàng chục triệu người dùng.','[\"Figma\", \"UI/UX Design\", \"User Research\", \"Wireframing\", \"Design System\"]','[\"Thành thạo Figma\", \"Tư duy thiết kế lấy người dùng làm trung tâm (User-Centered Design)\"]',3,'2026-12-31 23:59:59.000000','2026-08-26 14:08:48.323510','2026-08-26 07:10:33.082705'),('40000000-0000-4000-8000-000000000007','32000000-0000-4000-8000-000000000002','Unity / C++ Game Developer Intern','it_software','active','public','TP. Hồ Chí Minh','full_time','4-6 tháng','Đại học / Cao đẳng','Lập trình logic gameplay, tối ưu hóa FPS, xử lý đồng bộ mạng cho các dự án game multiplayer bằng Unity/C# hoặc Unreal/C++.','Mức phụ cấp thực tập 8.000.000 - 12.000.000 VNĐ; Trang bị máy tính cấu hình cao; Đào tạo Game Engine chuyên sâu.','[\"Unity\", \"C#\", \"C++\", \"Data Structures\", \"Game Mathematics\"]','[\"Nắm vững cấu trúc dữ liệu, giải thuật và toán học máy tính\", \"Đã từng phát triển game demo trên Unity\"]',5,'2026-12-31 23:59:59.000000','2026-08-26 14:08:48.323510','2026-08-26 07:10:33.082705'),('40000000-0000-4000-8000-000000000008','32000000-0000-4000-8000-000000000002','VNG Youth Discovery: Trải nghiệm Sáng tạo Game & Công nghệ Số','design_media','active','partner_schools','TP. Hồ Chí Minh','part_time','1 tháng','Trung học Phổ thông','Chương trình khám phá quy trình làm Game và sản phẩm số: từ ý tưởng kịch bản, thiết kế nhân vật đến trải nghiệm lập trình đơn giản.','Giấy chứng nhận trải nghiệm sáng tạo VNG; Tham gia cuộc thi ý tưởng Game dành cho học sinh THPT.','[\"Sáng tạo nội dung\", \"Kể chuyện (Storytelling)\", \"Tư duy thẩm mỹ\", \"Làm việc nhóm\"]','[\"Dành