INSERT INTO `learner_ai_catalog_items` VALUES ('50000000-0000-4000-8000-000000000001','project','data_analysis','Ứng dụng AI phân loại rác & Tái chế thông minh trong học đường (EcoSmart AI)','Vấn đề: Việc phân loại rác trong khuôn viên còn thiếu phản hồi tức thời và dữ liệu để đo hiệu quả thay đổi hành vi. Người dùng: sinh viên, đơn vị vận hành khuôn viên và câu lạc bộ môi trường Đại học FPT. Hạng mục chính: xây dựng tập dữ liệu hình ảnh có kiểm soát, thử nghiệm mô hình phân loại, thiết kế cơ chế tích điểm và đo lường Sản phẩm bàn giao: một nguyên mẫu AI phân loại rác, dashboard tác động và tài liệu nêu rõ giới hạn của mô hình.','published','2027-12-31 17:00:00','{}',12,0,'/app/learner/project.php?id=50000000-0000-4000-8000-000000000001','{\"type\":\"view_project\",\"project_id\":\"50000000-0000-4000-8000-000000000001\"}','22000000-b512-4ede-852b-f4a508f3e837','22000000-b512-4ede-852b-f4a508f3e837','2026-08-30 00:00:00','Đại học FPT','Khuôn viên Đại học FPT','intermediate','[{\"code\":\"python\",\"minimum_score\":55,\"label\":\"Lập trình Python\"},{\"code\":\"data_analysis\",\"minimum_score\":55,\"label\":\"Phân tích dữ liệu\"},{\"code\":\"teamwork\",\"minimum_score\":55,\"label\":\"Làm việc nhóm\"}]','[{\"code\":\"problem_solving\",\"label\":\"Giải quyết vấn đề\"},{\"code\":\"leadership\",\"label\":\"Lãnh đạo\"}]','[\"college\"]'),('50000000-0000-4000-8000-000000000002','project','creative_design','Game Giáo dục 3D: Hành trình Khám phá Di sản Lịch sử Việt Nam (HeritageQuest)','Vấn đề: Nội dung lịch sử cần một hình thức tương tác hấp dẫn nhưng vẫn phải tôn trọng tính chính xác và bối cảnh văn hóa. Người dùng: sinh viên, giảng viên và người học trẻ quan tâm đến di sản Việt Nam. Hạng mục chính: nghiên cứu nguồn lịch sử, thiết kế nhiệm vụ và môi trường 3D, kiểm thử trải nghiệm cùng độ chính xác nội dung Sản phẩm bàn giao: một vertical slice game 3D, hồ sơ nguồn tham khảo và báo cáo kiểm thử trải nghiệm học tập.','published','2027-12-31 17:00:00','{}',12,0,'/app/learner/project.php?id=50000000-0000-4000-8000-000000000002','{\"type\":\"view_project\",\"project_id\":\"50000000-0000-4000-8000-000000000002\"}','da811c4f-2f74-4fdd-80b0-dd6f26109783','da811c4f-2f74-4fdd-80b0-dd6f26109783','2026-08-30 00:00:00','Cao đẳng Quốc tế BTEC FPT','Khuôn viên BTEC FPT','intermediate','[{\"code\":\"creative_design\",\"minimum_score\":55,\"label\":\"Thiết kế sáng tạo\"},{\"code\":\"research\",\"minimum_score\":50,\"label\":\"Nghiên cứu\"},{\"code\":\"teamwork\",\"minimum_score\":55,\"label\":\"Làm việc nhóm\"}]','[{\"code\":\"communication\",\"label\":\"Giao tiếp\"},{\"code\":\"problem_solving\",\"label\":\"Giải quyết vấn đề\"}]','[\"college\"]'),('50000000-0000-4000-8000-000000000003','project','entrepreneurship','Nền tảng Sàn kết nối Nông sản số cho Hợp tác xã Thanh niên Khởi nghiệp (AgriBridge)','Vấn đề: Sản phẩm OCOP của các hợp tác xã thanh niên khó tiếp cận khách hàng thành thị và thiếu dữ liệu truy xuất dễ hiểu. Người dùng: hợp tác xã thanh niên, người mua thành thị và nhóm vận hành sàn. Hạng mục chính: nghiên cứu hành trình mua hàng, thiết kế gian hàng và QR truy xuất, thử nghiệm mô hình doanh thu cùng đối tác Sản phẩm bàn giao: một sàn thương mại điện tử mẫu, bộ hồ sơ sản phẩm minh bạch và dashboard theo dõi chuyển đổi.','published','2027-12-31 17:00:00','{}',12,0,'/app/learner/project.php?id=50000000-0000-4000-8000-000000000003','{\"type\":\"view_project\",\"project_id\":\"50000000-0000-4000-8000-000000000003\"}','22000000-b512-4ede-852b-f4a508f3e837','22000000-b512-4ede-852b-f4a508f3e837','2026-08-30 00:00:00','Đại học FPT','Khuôn viên Đại học FPT','intermediate','[{\"code\":\"entrepreneurship\",\"minimum_score\":55,\"label\":\"Khởi nghiệp\"},{\"code\":\"communication\",\"minimum_score\":60,\"label\":\"Giao tiếp\"},{\"code\":\"teamwork\",\"minimum_score\":55,\"label\":\"Làm việc nhóm\"}]','[{\"code\":\"data_analysis\",\"label\":\"Phân tích dữ liệu\"},{\"code\":\"leadership\",\"label\":\"Lãnh đạo\"}]','[\"college\"]'),('50000000-0000-4000-8000-000000000004','project','problem_solving','Hệ thống Cảnh báo Sớm An toàn Mạng & Phòng chống Bắt nạt Học đường (EduShield)','Vấn đề: Các dấu hiệu bắt nạt và lừa đảo trực tuyến thường được phát hiện quá muộn trong môi trường học đường. Người dùng: học sinh, giáo viên chủ nhiệm và bộ phận tư vấn học đường của THPT Nguyễn Trãi. Hạng mục chính: khảo sát tình huống rủi ro, xây dựng bộ quy tắc cảnh báo, thử nghiệm quy trình tiếp nhận an toàn Sản phẩm bàn giao: một nguyên mẫu cảnh báo sớm kèm cẩm nang phản hồi và báo cáo thử nghiệm bảo vệ quyền riêng tư.','published','2027-12-31 17:00:00','{}',12,0,'/app/learner/project.php?id=50000000-0000-4000-8000-000000000004','{\"type\":\"view_project\",\"project_id\":\"50000000-0000-4000-8000-000000000004\"}','20000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','2026-08-30 00:00:00','THPT Nguyễn Trãi','12 Sư Vạn Hạnh, Quận 10, TP. Hồ Chí Minh','beginner','[{\"code\":\"problem_solving\",\"minimum_score\":55,\"label\":\"Giải quyết vấn đề\"},{\"code\":\"communication\",\"minimum_score\":55,\"label\":\"Giao tiếp\"}]','[{\"code\":\"research\",\"label\":\"Nghiên cứu\"},{\"code\":\"leadership\",\"label\":\"Lãnh đạo\"}]','[\"high\"]'),('51000000-0000-4000-8000-000000000001','project','a','Trợ lý AI Ôn tập Cá nhân hóa cho Học sinh THPT','Vấn đề: Học sinh chưa có một công cụ giúp nhận biết phần kiến thức yếu và sắp xếp nội dung ôn tập theo tiến độ cá nhân. Người dùng: học sinh lớp 10 đến lớp 12 và giáo viên bộ môn tại THPT Nguyễn Trãi. Hạng mục chính: phân tích nhu cầu học tập, xây dựng logic gợi ý bằng Python, đánh giá lời giải thích với người dùng Sản phẩm bàn giao: một trợ lý ôn tập có bảng tiến độ, gợi ý bài học và báo cáo kiểm thử tính hữu ích, minh bạch.','published','2027-12-31 17:00:00','{}',12,0,'/app/learner/project.php?id=51000000-0000-4000-8000-000000000001','{\"type\":\"view_project\",\"project_id\":\"51000000-0000-4000-8000-000000000001\"}','20000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','2026-08-30 00:00:00','THPT Nguyễn Trãi','12 Sư Vạn Hạnh, Quận 10, TP. Hồ Chí Minh','beginner','[{\"code\":\"python\",\"minimum_score\":70,\"label\":\"Lập trình Python\"},{\"code\":\"data_analysis\",\"minimum_score\":65,\"label\":\"Phân tích dữ liệu\"},{\"code\":\"communication\",\"minimum_score\":60,\"label\":\"Giao tiếp\"}]','[{\"code\":\"research\",\"label\":\"Nghiên cứu\"},{\"code\":\"problem_solving\",\"label\":\"Giải quyết vấn đề\"}]','[\"high\"]'),('51000000-0000-4000-8000-000000000002','project','a','Bảng Điều khiển Dữ liệu Học tập và Chuyên cần','Vấn đề: Dữ liệu điểm số và chuyên cần đang phân tán nên giáo viên khó nhận biết sớm học sinh cần được hỗ trợ. Người dùng: ban học tập, giáo viên chủ nhiệm và học sinh THPT Nguyễn Trãi. Hạng mục chính: chuẩn hóa dữ liệu mẫu, xây dựng chỉ số học tập, thiết kế dashboard và kiểm tra khả năng đọc hiểu Sản phẩm bàn giao: một dashboard bảo vệ dữ liệu cá nhân, có bộ lọc lớp, cảnh báo xu hướng và tài liệu giải thích chỉ số.','published','2027-12-31 17:00:00','{}',12,0,'/app/learner/project.php?id=51000000-0000-4000-8000-000000000002','{\"type\":\"view_project\",\"project_id\":\"51000000-0000-4000-8000-000000000002\"}','20000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','2026-08-30 00:00:00','THPT Nguyễn Trãi','12 Sư Vạn Hạnh, Quận 10, TP. Hồ Chí Minh','beginner','[{\"code\":\"data_analysis\",\"minimum_score\":65,\"label\":\"Phân tích dữ liệu\"},{\"code\":\"python\",\"minimum_score\":70,\"label\":\"Lập trình Python\"},{\"code\":\"teamwork\",\"minimum_score\":60,\"label\":\"Làm việc nhóm\"}]','[{\"code\":\"research\",\"label\":\"Nghiên cứu\"},{\"code\":\"communication\",\"label\":\"Giao tiếp\"}]','[\"high\"]'),('51000000-0000-4000-8000-000000000003','project','research','GreenSchool Map — Bản đồ Sống xanh trong Khuôn viên','Vấn đề: Nhà trường chưa có bản đồ trực quan ghi nhận điểm xanh, nơi phân loại rác và khu vực cần cải thiện môi trường. Người dùng: toàn thể học sinh, câu lạc bộ môi trường và tổ quản trị cơ sở vật chất. Hạng mục chính: khảo sát thực địa theo nhóm, chuẩn hóa vị trí và ảnh minh chứng, thiết kế bản đồ cùng đề xuất cải thiện Sản phẩm bàn giao: một bản đồ số tương tác, bộ dữ liệu đã kiểm chứng và kế hoạch hành động xanh theo từng khu vực.','published','2027-12-31 17:00:00','{}',12,0,'/app/learner/project.php?id=51000000-0000-4000-8000-000000000003','{\"type\":\"view_project\",\"project_id\":\"51000000-0000-4000-8000-000000000003\"}','20000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','2026-08-30 00:00:00','THPT Nguyễn Trãi','12 Sư Vạn Hạnh, Quận 10, TP. Hồ Chí Minh','introductory','[{\"code\":\"research\",\"minimum_score\":45,\"label\":\"Nghiên cứu\"},{\"code\":\"teamwork\",\"minimum_score\":55,\"label\":\"Làm việc nhóm\"}]','[{\"code\":\"data_analysis\",\"label\":\"Phân tích dữ liệu\"},{\"code\":\"leadership\",\"label\":\"Lãnh đạo\"}]','[\"high\"]'),('51000000-0000-4000-8000-000000000004','project','problem_solving','SafeNet Student — Cẩm nang Nhận diện Lừa đảo Trực tuyến','Vấn đề: Học sinh tiếp xúc với nhiều thông điệp lừa đảo nhưng thiếu tình huống thực hành để nhận diện và phản ứng an toàn. Người dùng: học sinh THPT, phụ huynh và giáo viên phụ trách kỹ năng số. Hạng mục chính: thu thập mẫu tình huống đã ẩn danh, phân loại dấu hiệu lừa đảo, thiết kế nội dung hướng dẫn dễ hiểu Sản phẩm bàn giao: một cẩm nang số có câu hỏi tình huống, cây quyết định phản ứng và bộ tài liệu truyền thông học đường.','published','2027-12-31 17:00:00','{}',12,0,'/app/learner/project.php?id=51000000-0000-4000-8000-000000000004','{\"type\":\"view_project\",\"project_id\":\"51000000-0000-4000-8000-000000000004\"}','20000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','2026-08-30 00:00:00','THPT Nguyễn Trãi','12 Sư Vạn Hạnh, Quận 10, TP. Hồ Chí Minh','introductory','[{\"code\":\"communication\",\"minimum_score\":55,\"label\":\"Giao tiếp\"},{\"code\":\"research\",\"minimum_score\":45,\"label\":\"Nghiên cứu\"}]','[{\"code\":\"problem_solving\",\"label\":\"Giải quyết vấn đề\"},{\"code\":\"leadership\",\"label\":\"Lãnh đạo\"}]','[\"high\"]'),('51000000-0000-4000-8000-000000000005','project','creative_design','Ký ức Nguyễn Trãi — Bảo tàng Số Lịch sử Nhà trường','Vấn đề: Tư liệu lịch sử của nhà trường chưa được kể lại theo một trải nghiệm số hấp dẫn và dễ tiếp cận với học sinh mới. Người dùng: học sinh, cựu học sinh, giáo viên và khách tham quan THPT Nguyễn Trãi. Hạng mục chính: nghiên cứu và xác minh tư liệu, xây dựng câu chuyện theo mốc thời gian, thiết kế triển lãm số có chú thích Sản phẩm bàn giao: một bảo tàng số responsive gồm bộ sưu tập đã cấp quyền, dòng thời gian và hướng dẫn đóng góp tư liệu.','published','2027-12-31 17:00:00','{}',12,0,'/app/learner/project.php?id=51000000-0000-4000-8000-000000000005','{\"type\":\"view_project\",\"project_id\":\"51000000-0000-4000-8000-000000000005\"}','20000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','2026-08-30 00:00:00','THPT Nguyễn Trãi','12 Sư Vạn Hạnh, Quận 10, TP. Hồ Chí Minh','beginner','[{\"code\":\"creative_design\",\"minimum_score\":45,\"label\":\"Thiết kế sáng tạo\"},{\"code\":\"communication\",\"minimum_score\":55,\"label\":\"Giao tiếp\"}]','[{\"code\":\"research\",\"label\":\"Nghiên cứu\"},{\"code\":\"teamwork\",\"label\":\"Làm việc nhóm\"}]','[\"high\"]'),('51000000-0000-4000-8000-000000000006','project','logi','SmartClass IoT — Giám sát Chất lượng Không khí Lớp học','Vấn đề: Lớp học chưa có dữ liệu liên tục về nhiệt độ, độ ẩm và chất lượng không khí để điều chỉnh thông gió hợp lý. Người dùng: học sinh, giáo viên và tổ quản trị phòng học của THPT Nguyễn Trãi. Hạng mục chính: lắp cảm biến mẫu an toàn, thu thập và làm sạch dữ liệu, xây dựng cảnh báo cùng dashboard theo thời gian Sản phẩm bàn giao: một trạm đo thử nghiệm, dashboard Python và báo cáo khuyến nghị vận hành lớp học dựa trên dữ liệu.','published','2027-12-31 17:00:00','{}',12,0,'/app/learner/project.php?id=51000000-0000-4000