DROP TABLE IF EXISTS `learner_ai_consent_events`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `learner_ai_consent_events` (
  `id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `studentId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `scope` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `action` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `policyVersion` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `occurredAt` datetime(6) NOT NULL,
  `requestId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_learner_ai_consent_events_student_scope_occurred_request` (`studentId`,`scope`,`occurredAt`,`requestId`),
  KEY `idx_learner_ai_consent_events_student_scope_occurred` (`studentId`,`scope`,`occurredAt`),
  CONSTRAINT `fk_learner_ai_consent_events_student` FOREIGN KEY (`studentId`) REFERENCES `student_profiles` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `chk_learner_ai_consent_events_action` CHECK ((`action` in (_utf8mb4'granted',_utf8mb4'revoked'))),
  CONSTRAINT `chk_learner_ai_consent_events_scope` CHECK ((`scope` in (_utf8mb4'assessment',_utf8mb4'skills',_utf8mb4'activity',_utf8mb4'evaluation')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

