--
-- Table structure for table `learner_ai_evaluation_runs`
--

DROP TABLE IF EXISTS `learner_ai_evaluation_runs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `learner_ai_evaluation_runs` (
  `id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `studentId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `subjectRef` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `subjectRefVersion` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `attemptKey` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `ruleRunId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `modelRunId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `snapshotId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `educationBand` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `cohortTagsJson` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `provider` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `modelVersion` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `promptVersion` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `ruleVersion` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `evaluatorVersion` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `evaluationRevision` int unsigned NOT NULL DEFAULT '1',
  `supersedesEvaluationId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `inputSnapshotHash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `consentPolicyVersion` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `consentDecisionHash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `consentEvaluatedAt` datetime(6) NOT NULL,
  `schemaValid` tinyint unsigned NOT NULL,
  `evidenceCoverage` decimal(7,6) NOT NULL,
  `evidenceMatched` int unsigned NOT NULL,
  `evidenceRequired` int unsigned NOT NULL,
  `unsupportedClaimCount` int unsigned NOT NULL,
  `unsafeOutputCount` int unsigned NOT NULL,
  `resultType` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `fallbackReason` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `providerErrorCategory` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `latencyMs` decimal(12,3) DEFAULT NULL,
  `inputTokens` int unsigned DEFAULT NULL,
  `outputTokens` int unsigned DEFAULT NULL,
  `estimatedCost` decimal(18,8) DEFAULT NULL,
  `costCurrency` char(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `retentionClass` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'evaluation_standard',
  `evaluatedAt` datetime(6) NOT NULL,
  `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_learner_ai_evaluation_id_student` (`id`,`studentId`),
  UNIQUE KEY `uq_learner_ai_evaluation_attempt_revision` (`attemptKey`,`evaluatorVersion`,`evaluationRevision`),
  UNIQUE KEY `uq_learner_ai_evaluation_model_revision` (`modelRunId`,`evaluatorVersion`,`evaluationRevision`),
  UNIQUE KEY `uq_learner_ai_evaluation_superseded_once` (`supersedesEvaluationId`),
  KEY `idx_learner_ai_evaluation_student_time` (`studentId`,`evaluatedAt`),
  KEY `idx_learner_ai_evaluation_band_status_time` (`educationBand`,`status`,`evaluatedAt`),
  KEY `idx_learner_ai_evaluation_provider_model_time` (`provider`,`modelVersion`,`evaluatedAt`),
  KEY `idx_learner_ai_evaluation_gate_time` (`schemaValid`,`unsupportedClaimCount`,`unsafeOutputCount`,`evaluatedAt`),
  KEY `idx_learner_ai_evaluation_retention_time` (`retentionClass`,`createdAt`),
  KEY `fk_learner_ai_evaluation_rule_owner` (`ruleRunId`,`studentId`),
  KEY `fk_learner_ai_evaluation_model_owner` (`modelRunId`,`studentId`),
  KEY `fk_learner_ai_evaluation_snapshot_owner` (`snapshotId`,`studentId`),
  KEY `fk_learner_ai_evaluation_supersedes_owner` (`supersedesEvaluationId`,`studentId`),
  CONSTRAINT `fk_learner_ai_evaluation_model_owner` FOREIGN KEY (`modelRunId`, `studentId`) REFERENCES `learner_recommendation_runs` (`id`, `studentId`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_learner_ai_evaluation_rule_owner` FOREIGN KEY (`ruleRunId`, `studentId`) REFERENCES `learner_recommendation_runs` (`id`, `studentId`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_learner_ai_evaluation_snapshot_owner` FOREIGN KEY (`snapshotId`, `studentId`) REFERENCES `learner_recommendation_input_snapshots` (`id`, `studentId`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_learner_ai_evaluation_student` FOREIGN KEY (`studentId`) REFERENCES `student_profiles` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_learner_ai_evaluation_supersedes_owner` FOREIGN KEY (`supersedesEvaluationId`, `studentId`) REFERENCES `learner_ai_evaluation_runs` (`id`, `studentId`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `chk_learner_ai_evaluation_attempt_key` CHECK (regexp_like(`attemptKey`,_utf8mb4'^[0-9a-f]{64}$')),
  CONSTRAINT `chk_learner_ai_evaluation_band` CHECK ((`educationBand` in (_utf8mb4'high',_utf8mb4'college'))),
  CONSTRAINT `chk_learner_ai_evaluation_cohort_json` CHECK (json_valid(`cohortTagsJson`)),
  CONSTRAINT `chk_learner_ai_evaluation_cost` CHECK ((((`estimatedCost` is null) and (`costCurrency` is null)) or ((`estimatedCost` is not null) and (`estimatedCost` >= 0) and regexp_like(`costCurrency`,_utf8mb4'^[A-Z]{3}$')))),
  CONSTRAINT `chk_learner_ai_evaluation_coverage` CHECK (((`evidenceCoverage` >= 0) and (`evidenceCoverage` <= 1) and (`evidenceMatched` <= `evidenceRequired`))),
  CONSTRAINT `chk_learner_ai_evaluation_fallback_reason` CHECK (((`fallbackReason` is null) or (`fallbackReason` in (_utf8mb4'consent_missing',_utf8mb4'consent_revoked',_utf8mb4'consent_changed',_utf8mb4'model_disabled',_utf8mb4'rate_limited',_utf8mb4'provider_disabled',_utf8mb4'provider_unavailable',_utf8mb4'provider_rejected',_utf8mb4'malformed_response',_utf8mb4'invalid_request',_utf8mb4'invalid_model_response',_utf8mb4'unsafe_output',_utf8mb4'unsupported_claim',_utf8mb4'schema_invalid',_utf8mb4'version_mismatch',_utf8mb4'reconciliation_required')))),
  CONSTRAINT `chk_learner_ai_evaluation_hashes` CHECK ((regexp_like(`inputSnapshotHash`,_utf8mb4'^[0-9a-f]{64}$') and regexp_like(`consentDecisionHash`,_utf8mb4'^[0-9a-f]{64}$'))),
  CONSTRAINT `chk_learner_ai_evaluation_latency` CHECK (((`latencyMs` is null) or (`latencyMs` >= 0))),
  CONSTRAINT `chk_learner_ai_evaluation_model_run_presence` CHECK ((((`resultType` = _utf8mb4'blocked_before_call') and (`modelRunId` is null)) or ((`resultType` in (_utf8mb4'model',_utf8mb4'rule_fallback')) and (`modelRunId` is not null)))),
  CONSTRAINT `chk_learner_ai_evaluation_provider_error` CHECK (((`providerErrorCategory` is null) or (`providerErrorCategory` in (_utf8mb4'rate_limited',_utf8mb4'provider_disabled',_utf8mb4'provider_unavailable',_utf8mb4'provider_rejected',_utf8mb4'malformed_response',_utf8mb4'invalid_request',_utf8mb4'unknown_outcome')))),
  CONSTRAINT `chk_learner_ai_evaluation_result_status` CHECK ((((`resultType` = _utf8mb4'model') and (`status` = _utf8mb4'completed') and (`fallbackReason` is null) and (`providerErrorCategory` is null)) or ((`resultType` = _utf8mb4'rule_fallback') and (`status` in (_utf8mb4'fallback',_utf8mb4'gate_failed')) and (`fallbackReason` is not null)) or ((`resultType` = _utf8mb4'blocked_before_call') and (`status` = _utf8mb4'blocked') and (`fallbackReason` is not null) and (`latencyMs` is null) and (`inputTokens` is null) and (`outputTokens` is null) and (`estimatedCost` is null) and (`costCurrency` is null)))),
  CONSTRAINT `chk_learner_ai_evaluation_result_type` CHECK ((`resultType` in (_utf8mb4'model',_utf8mb4'rule_fallback',_utf8mb4'blocked_before_call'))),
  CONSTRAINT `chk_learner_ai_evaluation_retention` CHECK ((`retentionClass` in (_utf8mb4'evaluation_standard',_utf8mb4'incident_hold',_utf8mb4'legal_hold'))),
  CONSTRAINT `chk_learner_ai_evaluation_revision` CHECK ((((`evaluationRevision` = 1) and (`supersedesEvaluationId` is null)) or ((`evaluationRevision` > 1) and (`supersedesEvaluationId` is not null)))),
  CONSTRAINT `chk_learner_ai_evaluation_schema_valid` CHECK ((`schemaValid` in (0,1))),
  CONSTRAINT `chk_learner_ai_evaluation_status` CHECK ((`status` in (_utf8mb4'completed',_utf8mb4'gate_failed',_utf8mb4'blocked',_utf8mb4'fallback'))),
  CONSTRAINT `chk_learner_ai_evaluation_subject_ref` CHECK (regexp_like(`subjectRef`,_utf8mb4'^[0-9a-f]{64}$')),
  CONSTRAINT `chk_learner_ai_evaluation_subject_ref_version` CHECK (regexp_like(`subjectRefVersion`,_utf8mb4'^[A-Za-z0-9._-]{1,50}$')),
  CONSTRAINT `chk_learner_ai_evaluation_time_order` CHECK (((`consentEvaluatedAt` <= `evaluatedAt`) and (`evaluatedAt` <= `createdAt`)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

