--
-- Table structure for table `learner_ai_roadmap_phases`
--

DROP TABLE IF EXISTS `learner_ai_roadmap_phases`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `learner_ai_roadmap_phases` (
  `id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `roadmapId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `position` tinyint unsigned NOT NULL,
  `startDay` tinyint unsigned NOT NULL,
  `endDay` tinyint unsigned NOT NULL,
  `code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `goal` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `skillFocus` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `deliverable` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `effortLabel` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `metricLabel` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `evidenceJson` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_learner_ai_roadmap_phases_position` (`roadmapId`,`position`),
  KEY `idx_learner_ai_roadmap_phases_roadmap` (`roadmapId`),
  CONSTRAINT `fk_learner_ai_roadmap_phases_roadmap` FOREIGN KEY (`roadmapId`) REFERENCES `learner_ai_roadmaps` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `chk_learner_ai_roadmap_phases_evidence_json` CHECK (json_valid(`evidenceJson`)),
  CONSTRAINT `chk_learner_ai_roadmap_phases_range` CHECK ((((`position` = 1) and (`startDay` = 0) and (`endDay` = 30)) or ((`position` = 2) and (`startDay` = 31) and (`endDay` = 60)) or ((`position` = 3) and (`startDay` = 61) and (`endDay` = 90))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

