--
-- Table structure for table `learner_ai_roadmap_tasks`
--

DROP TABLE IF EXISTS `learner_ai_roadmap_tasks`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `learner_ai_roadmap_tasks` (
  `id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `phaseId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `position` tinyint unsigned NOT NULL,
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` varchar(1500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `estimatedMinutes` smallint unsigned NOT NULL,
  `actionType` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `targetType` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `targetId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `evidenceJson` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_learner_ai_roadmap_tasks_position` (`phaseId`,`position`),
  KEY `idx_learner_ai_roadmap_tasks_phase` (`phaseId`),
  CONSTRAINT `fk_learner_ai_roadmap_tasks_phase` FOREIGN KEY (`phaseId`) REFERENCES `learner_ai_roadmap_phases` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `chk_learner_ai_roadmap_tasks_action` CHECK ((((`actionType` = _utf8mb4'self_task') and (`targetType` is null) and (`targetId` is null)) or ((`actionType` = _utf8mb4'register_activity') and (`targetType` = _utf8mb4'activity') and (`targetId` is not null)))),
  CONSTRAINT `chk_learner_ai_roadmap_tasks_evidence_json` CHECK (json_valid(`evidenceJson`)),
  CONSTRAINT `chk_learner_ai_roadmap_tasks_minutes` CHECK ((`estimatedMinutes` between 5 and 1440)),
  CONSTRAINT `chk_learner_ai_roadmap_tasks_position` CHECK ((`position` between 1 and 5))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

