INSERT INTO `learner_ai_roadmap_tasks` VALUES ('00660af9-597b-4419-8e20-b221ab1b7f42','8a1de756-43cd-45d5-8aac-5a270a7d748a',2,'Chuẩn bị câu chuyện','Trình bày vấn đề, cách thử nghiệm, kết quả và bài học.',45,'self_task',NULL,NULL,'[\"evidence-003\"]','2026-08-26 05:08:36.000000'),('01d7a78f-597f-4f44-95e8-402e5dc81057','4886d51a-3099-4264-9a54-bbb54b0012eb',3,'Đánh giá và định hình mục tiêu cho giai đoạn tiếp theo','Nhìn nhận lại kết quả đạt được sau 90 ngày, đúc kết các bài học về làm việc nhóm và xác định kỹ năng trọng tâm cần bồi dưỡng thêm.',60,'self_task',NULL,NULL,'[\"evidence-002\",\"evidence-003\"]','2026-08-26 05:09:11.000000'),('03b1572d-48c4-4544-883b-91cb8862f64e','2502f190-cee9-4228-af89-f0db77efc252',3,'Thực hiện phân tích dữ liệu cơ bản','Thu thập và xử lý các thông tin cần thiết phục vụ cho việc đánh giá kết quả thực hiện đề tài.',90,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-24 15:21:04.000000'),('03cb050d-38b5-4e2f-89b5-25d495ff8ffd','f7a369a7-7220-43df-86ad-b32b56bc986b',3,'Thu thập phản hồi','Xin phản hồi từ ít nhất hai người và ghi lại điều học được.',45,'self_task',NULL,NULL,'[\"evidence-001\"]','2026-08-26 05:08:36.000000'),('050bc379-2465-45ab-8068-6798c71cb0b5','54876e78-8ebe-4543-bbcd-8f04d07a1ebe',1,'Chọn phản hồi ưu tiên','Phân loại phản hồi và chọn một thay đổi quan trọng.',45,'self_task',NULL,NULL,'[\"evidence-002\"]','2026-08-26 05:08:36.000000'),('06a28e1c-fdad-58f4-a16c-425d01f60a07','edfca528-8316-5713-bb88-4c3af41a5371',2,'Chuẩn bị CV định hướng','Điều chỉnh CV cho vị trí Chuyên viên vận hành chuỗi cung ứng và liên kết sản phẩm minh chứng.',120,'self_task',NULL,NULL,'[\"63a115ff-6acc-5bdb-aaf8-e6e2654ff041\"]','2026-08-25 18:49:00.000000'),('08714a02-e56f-5c46-935e-ff0f9876bae6','62a1d2cd-97e8-51d8-a485-164040409753',2,'Thiết lập mục tiêu SMART','Xây dựng mục tiêu 90 ngày gắn với định hướng Kỹ sư nền tảng đám mây.',75,'self_task',NULL,NULL,'[\"d2563021-c020-5018-9bbb-b90f4627b617\"]','2026-08-25 19:03:00.000000'),('093963d1-5ee7-5f8c-931d-77c2ba51e2c7','a4049fe8-f128-5ae8-ac64-311db2d2fd42',2,'Chuẩn bị CV định hướng','Điều chỉnh CV cho vị trí Chuyên viên trải nghiệm khách hàng và liên kết sản phẩm minh chứng.',120,'self_task',NULL,NULL,'[\"bcb6d9fe-4413-57fb-959c-211a2e17777a\"]','2026-08-25 19:10:00.000000'),('0a2cb33f-f0dc-5325-91b1-f358cb221170','bb6a448f-787b-5b06-b94a-94683bc00d60',2,'Thiết lập mục tiêu SMART','Xây dựng mục tiêu 90 ngày gắn với định hướng Chuyên viên phân tích dữ liệu.',75,'self_task',NULL,NULL,'[\"8c169adf-2353-58f0-8b77-21719f7ce057\"]','2026-08-25 18:21:00.000000'),('0cb9e5bb-17b5-4978-b90b-17c5a8fb997b','a8bfbfd4-92b2-49c6-a365-8a95b1a2eb67',3,'Khảo sát và phân loại các câu lạc bộ học thuật','Tìm hiểu và lập danh sách so sánh 3 câu lạc bộ công nghệ hoặc dự án tại trường phù hợp với định hướng thiết kế giải pháp.',75,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-003\"]','2026-08-26 05:15:08.000000'),('0ed5703b-b941-59a3-ab9c-7ffbc84ec60b','2ecf4e0b-fece-5678-b5ba-a22384cd5633',1,'Phân tích hồ sơ năng lực','Đọc lại bốn kết quả đánh giá, ghi ba thế mạnh và hai điểm cần cải thiện.',60,'self_task',NULL,NULL,'[\"4afd7d1f-b372-543f-aa9e-bc00e34193d7\"]','2026-08-25 18:07:00.000000'),('0ff50d09-62f5-4153-abfd-072c37cb930a','b01cf096-a8f5-4e6d-8519-04d9aca7c9e5',1,'Lập danh sách các lĩnh vực quan tâm và kỹ năng cốt lõi','Ghi chép lại các chủ đề bạn hứng thú về quản lý, công nghệ hoặc sáng tạo, đồng thời tự đánh giá mức độ thuần thục hiện tại.',60,'self_task',NULL,NULL,'[\"evidence-001\"]','2026-08-24 15:40:29.000000'),('1313d8ea-ee65-5328-905f-a296933ed888','a4049fe8-f128-5ae8-ac64-311db2d2fd42',3,'Mô phỏng phỏng vấn','Thực hiện một buổi phỏng vấn thử, ghi phản hồi và kế hoạch cải thiện tiếp theo.',90,'self_task',NULL,NULL,'[\"b727f954-c3ae-5ff4-81fc-a58424fe319c\"]','2026-08-25 19:10:00.000000'),('13356cb0-a0fd-51ad-954f-daba8afa12b3','00eeab3f-6b43-5c95-82eb-e4db1aed3acb',1,'Xác định bài toán dự án','Chọn một vấn đề thực tế phù hợp ngành Phân tích dữ liệu và mô tả người dùng mục tiêu.',90,'self_task',NULL,NULL,'[\"8c169adf-2353-58f0-8b77-21719f7ce057\"]','2026-08-25 18:21:00.000000'),('155a97d3-7af9-4443-bdb1-995233234e90','5dbd4c3b-5abc-4d23-aeed-e04282ba54c9',2,'Xây dựng hồ sơ sản phẩm học tập cá nhân','Tổng hợp các sản phẩm, sơ đồ nghiên cứu và bài tập lớn tiêu biểu trong học kỳ vào một trang lưu trữ trực tuyến.',120,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-004\"]','2026-08-26 05:15:08.000000'),('15cf8aae-d3dc-52a8-9802-b2dcdf9ca8bb','a69872f4-8f11-5831-99d5-8db3ddfb7808',2,'Xây dựng sản phẩm thử nghiệm','Tạo phiên bản đầu tiên, lưu lại quyết định và bằng chứng tiến độ.',360,'self_task',NULL,NULL,'[\"2a44b91b-8bd6-5be1-a1ee-9cc0deec342c\"]','2026-08-25 18:42:00.000000'),('163eb865-2e6c-5098-be9f-b6ffc214895f','7558473a-3bdb-5bf9-aab9-92bfab325f8a',3,'Học mô-đun nền tảng','Hoàn thành một mô-đun cốt lõi của ngành Quản trị dịch vụ và ghi chép ví dụ ứng dụng.',240,'self_task',NULL,NULL,'[\"90c5ee93-441c-583d-bd55-6407459bde29\"]','2026-08-25 19:10:00.000000'),('1753b1dd-66c6-47fd-8637-b00a26e32dd7','41be4372-cfae-483a-8f17-29186718e7d0',1,'Tổng hợp và đóng gói hồ sơ dự án ứng dụng','Chuẩn hóa toàn bộ tài liệu mô tả, sơ đồ luồng dữ liệu và thiết kế giao diện thành một báo cáo dự án hoàn chỉnh.',180,'self_task',NULL,NULL,'[\"evidence-001\",\"evidence-002\",\"evidence-004\"]','2026-08-26 03:35:52.000000'),('1849b227-6d80-4243-aa57-932d147a8f25','a2502720-8ba6-42c2-8892-e53acf0b12f2',3,'Nhận đánh giá cuối kỳ','Xin nhận xét có cấu trúc và chọn mục tiêu tiếp theo.',45,'self_task',NULL,NULL,'[\"evidence-003\"]','2026-08-26 03:26:09.000000'),('18dc16e3-682b-5260-be8a-0eae7b66ab5f','d8983f7c-e675-5420-8f55-ff354743b56c',2,'Thiết lập mục tiêu SMART','Xây dựng mục tiêu 90 ngày gắn với định hướng Kỹ sư an toàn thông tin.',75,'self_task',NULL,NULL,'[\"643bf908-b554-5abd-847c-4d323e93c99c\"]','2026-08-25 18:35:00.000000'),('19d361b0-16ad-50f3-a048-d6f168d1971c','0cd7474b-0a25-5568-91fe-5def493e832e',1,'Xác định bài toán dự án','Chọn một vấn đề thực tế phù hợp ngành Quản trị dịch vụ và mô tả người dùng mục tiêu.',90,'self_task',NULL,NULL,'[\"700cc2f3-0e83-5ae0-a59e-91cdd50cea83\"]','2026-08-25 19:10:00.000000'),('1c4c4c9e-27c5-5023-94aa-e30d5b789fc9','bb6a448f-787b-5b06-b94a-94683bc00d60',3,'Học mô-đun nền tảng','Hoàn thành một mô-đun cốt lõi của ngành Phân tích dữ liệu và ghi chép ví dụ ứng dụng.',240,'self_task',NULL,NULL,'[\"ac6912c8-4e65-5e98-b67d-e3f76f3ff3ed\"]','2026-08-25 18:21:00.000000'),('1ca03f7c-7b76-5e90-b631-c169955c4ab3','d8983f7c-e675-5420-8f55-ff354743b56c',1,'Phân tích hồ sơ năng lực','Đọc lại bốn kết quả đánh giá, ghi ba thế mạnh và hai điểm cần cải thiện.',60,'self_task',NULL,NULL,'[\"4501e0b0-acc0-529a-ab14-e82d54ee3550\"]','2026-08-25 18:35:00.000000'),('1dd41be9-a0de-5ad3-b13e-fdd23aeca6d5','c9d27261-64f8-53df-a65b-171aa5928726',3,'Nhận phản hồi và cải tiến','Thu thập ít nhất hai phản hồi, ưu tiên thay đổi và hoàn thiện phiên bản thứ hai.',150,'self_task',NULL,NULL,'[\"cdeac990-f872-5d28-921d-6904910ed8ed\"]','2026-08-25 18:14:00.000000'),('20ae0a0d-1241-46a9-aaa8-5ed6274a881b','0acbe34f-147d-450a-a19c-dca06e910791',2,'Tạo phương án thử nghiệm','Phác thảo một giải pháp nhỏ có thể hoàn thành trong tuần.',45,'self_task',NULL,NULL,'[\"evidence-001\"]','2026-08-25 14:17:14.000000'),('21bdfc7d-8197-41ac-bd97-33c61bcc4146','414a28d3-ac68-49c2-a015-015beaac2c76',2,'Tạo phương án thử nghiệm','Phác thảo một giải pháp nhỏ có thể hoàn thành trong tuần.',45,'self_task',NULL,NULL,'[\"evidence-001\"]','2026-08-26 03:26:09.000000'),('2222d70c-c084-50c1-bfc5-0b294e46b1bf','b21064de-557b-5d6d-91ba-c268dccb415b',1,'Hoàn thiện portfolio','Viết case study nêu vấn đề, vai trò, quá trình, kết quả và bài học.',180,'self_task',NULL,NULL,'[\"ac6912c8-4e65-5e98-b67d-e3f76f3ff3ed\"]','2026-08-25 18:21:00.000000'),('232ce029-a5cf-4d38-8dd4-088563f3fb0b','2502f190-cee9-4228-af89-f0db77efc252',1,'Xây dựng đề cương dự án thực hành','Soạn thảo tài liệu mô tả mục tiêu, phạm vi