INSERT INTO `learner_ai_roadmaps` VALUES ('1147e9ce-ebf1-56bc-b71e-65f88f33ae3f','a49dadc0-65f0-5862-a380-34c2d43ecbc6','4b7f2061-985b-5875-915e-678ff3df4eb3',1,'learner-roadmap-1.0.0','active','Lộ trình 90 ngày dành cho Võ Đức Anh tập trung vào kỹ sư an toàn thông tin, dựa trên bốn bài đánh giá đã hoàn thành. Kế hoạch kết hợp học nền tảng, thực hành dự án và hoàn thiện hồ sơ năng lực có minh chứng.','{\"code\":\"ky_su_an_toan_thong_tin\",\"label\":\"Kỹ sư an toàn thông tin\",\"rationale\":\"Phù hợp với bình tĩnh xử lý sự cố, tư duy thực nghiệm và khả năng tìm nguyên nhân gốc và tổ hợp kết quả RIC / ISTP / DCIS.\"}','[{\"code\":\"ky_su_van_hanh_he_thong\",\"label\":\"Kỹ sư vận hành hệ thống\",\"rationale\":\"Khai thác nhóm năng lực liền kề trong kết quả đánh giá.\"},{\"code\":\"digital_project_coordination\",\"label\":\"Điều phối dự án số\",\"rationale\":\"Bổ sung lựa chọn phát triển kỹ năng tổ chức và cộng tác liên ngành.\"}]','[{\"category\":\"strength\",\"evidence_ref_ids\":[\"4501e0b0-acc0-529a-ab14-e82d54ee3550\",\"643bf908-b554-5abd-847c-4d323e93c99c\"],\"summary\":\"Bình tĩnh xử lý sự cố, tư duy thực nghiệm và khả năng tìm nguyên nhân gốc\",\"title\":\"Nền tảng nổi trội\"},{\"category\":\"potential\",\"evidence_ref_ids\":[\"cfe5f46a-d015-5e3c-817b-c76b61a41eae\",\"c6c194fc-96f3-5783-8c4a-b8a927485a3e\"],\"summary\":\"Có thể phát triển bền vững theo hướng kỹ sư an toàn thông tin thông qua dự án thực tế.\",\"title\":\"Tiềm năng nghề nghiệp\"},{\"category\":\"improvement\",\"evidence_ref_ids\":[\"643bf908-b554-5abd-847c-4d323e93c99c\",\"cfe5f46a-d015-5e3c-817b-c76b61a41eae\"],\"summary\":\"Chuẩn hóa tài liệu kỹ thuật và chia sẻ phát hiện với đồng đội\",\"title\":\"Ưu tiên cải thiện\"}]','high','{\"assessment_count\":4,\"complete_assessment_set\":true,\"synthetic_demo\":true}','seed-btec-vo-duc-anh','cb75949d62347a46c86f1bd4caeece7173cda105781518447a1b02668b7154c9','2026-08-25 18:35:00.000000',NULL,'2026-08-25 18:35:00.000000'),('1475356c-6df3-46f9-8da2-211b6cac6d3a','1e5c4644-36e3-47c1-8d94-cb4aada7b006','436449d0-f3c3-4c54-a4f4-5cfaf53e8e22',1,'learner-roadmap-1.0.0','active','Lộ trình 90 ngày hỗ trợ phát triển kỹ năng toàn diện, kết hợp tư duy logic, tổ chức công việc và khả năng thực thi thực tế nhằm định hình định hướng học tập và dự án cá nhân rõ ràng.','{\"code\":\"project_management_operations\",\"label\":\"Quản trị Dự án và Vận hành Kỹ thuật\",\"rationale\":\"Sự kết hợp giữa tư duy cấu trúc, tinh thần trách nhiệm và khả năng định hướng hành động thực tiễn hỗ trợ tốt việc lập kế hoạch và điều phối hoạt động.\"}','[{\"code\":\"creative_technical_design\",\"label\":\"Thiết kế và Ứng dụng Không gian Kỹ thuật\",\"rationale\":\"Khả năng tư duy hình ảnh và ngôn ngữ trực quan tạo điều kiện thuận lợi cho việc chuyển đổi ý tưởng sáng tạo thành giải pháp thực tế.\"},{\"code\":\"business_communication_analytics\",\"label\":\"Phân tích và Truyền thông Kinh doanh\",\"rationale\":\"Thế mạnh về diễn đạt thông tin và suy luận logic giúp hỗ trợ xây dựng giải pháp và truyền tải kế hoạch một cách thuyết phục.\"}]','[{\"category\":\"strength\",\"title\":\"Tư duy tổ chức và định hướng mục tiêu\",\"summary\":\"Thể hiện khả năng tiếp cận công việc một cách rõ ràng, chú trọng kết quả và duy trì tính ổn định trong quá trình triển khai nhiệm vụ.\",\"evidence_ref_ids\":[\"evidence-002\",\"evidence-003\"]},{\"category\":\"potential\",\"title\":\"Khả năng phối hợp đa dạng giữa logic và ngôn ngữ\",\"summary\":\"Tiềm năng kết nối dữ liệu, cấu trúc thông điệp và hình dung không gian giúp xử lý các vấn đề tổng hợp một cách linh hoạt.\",\"evidence_ref_ids\":[\"evidence-004\"]},{\"category\":\"improvement\",\"title\":\"Cân bằng giữa thực thi thực tế và nghiên cứu lý thuyết\",\"summary\":\"Cần tăng cường thói quen phân tích sâu trước khi thực thi để nâng cao tính bền vững cho các phương án xử lý công việc.\",\"evidence_ref_ids\":[\"evidence-001\"]}]','high','{\"assessment_count\":4,\"skill_count\":0,\"activity_count\":0,\"evaluation_count\":0}','chatcmpl-nmGMasDhKZqm1e8P_8GXiQk','d04b2e8fb9b68eae697950e6f950aef1541b0e543326ec1b4016b2e671e1ed55','2026-08-24 15:21:04.000000',NULL,'2026-08-24 15:21:04.000000'),('1d2ff34e-6d4b-5e66-b3df-fa5e35d1ecd0','f6d409d4-3387-5120-bc41-814bcffe589b','2a06a783-da1f-55b3-9a4e-09ee200db8fd',1,'learner-roadmap-1.0.0','active','Lộ trình 90 ngày dành cho Phạm Thảo Vy tập trung vào chuyên viên chiến lược nội dung số, dựa trên bốn bài đánh giá đã hoàn thành. Kế hoạch kết hợp học nền tảng, thực hành dự án và hoàn thiện hồ sơ năng lực có minh chứng.','{\"code\":\"chuyen_vien_chien_luoc_noi_dung_so\",\"label\":\"Chuyên viên chiến lược nội dung số\",\"rationale\":\"Phù hợp với giao tiếp thuyết phục, thấu hiểu người dùng và tổ chức hoạt động nhóm và tổ hợp kết quả ESA / ENFJ / IDSC.\"}','[{\"code\":\"quan_tri_thuong_hieu\",\"label\":\"Quản trị thương hiệu\",\"rationale\":\"Khai thác nhóm năng lực liền kề trong kết quả đánh giá.\"},{\"code\":\"digital_project_coordination\",\"label\":\"Điều phối dự án số\",\"rationale\":\"Bổ sung lựa chọn phát triển kỹ năng tổ chức và cộng tác liên ngành.\"}]','[{\"category\":\"strength\",\"evidence_ref_ids\":[\"d37b7333-f866-5edc-a6ce-52d5244f5d2f\",\"4a9e19f3-bd3a-538b-9bee-713ac6369e59\"],\"summary\":\"Giao tiếp thuyết phục, thấu hiểu người dùng và tổ chức hoạt động nhóm\",\"title\":\"Nền tảng nổi trội\"},{\"category\":\"potential\",\"evidence_ref_ids\":[\"bb3a5fc8-1199-590f-b2d6-50904c80682d\",\"ee93d485-4487-5750-81e1-cd8093b0dde0\"],\"summary\":\"Có thể phát triển bền vững theo hướng chuyên viên chiến lược nội dung số thông qua dự án thực tế.\",\"title\":\"Tiềm năng nghề nghiệp\"},{\"category\":\"improvement\",\"evidence_ref_ids\":[\"4a9e19f3-bd3a-538b-9bee-713ac6369e59\",\"bb3a5fc8-1199-590f-b2d6-50904c80682d\"],\"summary\":\"Bổ sung năng lực đọc chỉ số và thử nghiệm nội dung dựa trên dữ liệu\",\"title\":\"Ưu tiên cải thiện\"}]','high','{\"assessment_count\":4,\"complete_assessment_set\":true,\"synthetic_demo\":true}','seed-btec-pham-thao-vy','6d4825