DROP TABLE IF EXISTS `learner_recommendation_feedback`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `learner_recommendation_feedback` (
  `id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `studentId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `itemId` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `verdict` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `reasonCode` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `safeComment` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  KEY `idx_learner_recommendation_feedback_student_created` (`studentId`,`createdAt`),
  KEY `idx_learner_recommendation_feedback_item` (`itemId`),
  CONSTRAINT `fk_learner_recommendation_feedback_item` FOREIGN KEY (`itemId`) REFERENCES `learner_recommendation_items` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_learner_recommendation_feedback_student` FOREIGN KEY (`studentId`) REFERENCES `student_profiles` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `chk_learner_recommendation_feedback_safe_comment` CHECK (((`safeComment` is null) or (char_length(`safeComment`) <= 500))),
  CONSTRAINT `chk_learner_recommendation_feedback_verdict` CHECK ((`verdict` in (_utf8mb4'helpful',_utf8mb4'not_helpful',_utf8mb4'not_relevant',_utf8mb4'unsafe')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
