  `qualityFlagsJson` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `payloadJson` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `sourceUpdatedAt` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_learner_recommendation_input_snapshots_student_hash` (`studentId`,`contentHash`),
  UNIQUE KEY `uq_learner_recommendation_input_snapshots_id_student` (`id`,`studentId`),
  KEY `idx_learner_recommendation_input_snapshots_student_created` (`studentId`,`createdAt`),
