  CONSTRAINT `chk_learner_recommendation_input_snapshots_source_updated_json` CHECK (json_valid(`sourceUpdatedAt`))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
